#include <bits/stdc++.h>
using namespace std;

class Solution { public:
 int mostFrequent(vector<int>& nums,int key) {
  unordered_map<int,int> f; int ans=0,best=0;
  for(int i=1;i<(int)nums.size();++i) if(nums[i-1]==key) {
   int c=++f[nums[i]]; if(c>best){best=c;ans=nums[i];}
  }
  return ans;
 }
};
